#!/usr/bin/env python3
"""JSON Log Analyzer — CLI tool for parsing, filtering, aggregating JSON logs.

Usage:
    python3 jlog.py [options] <file>...
    python3 jlog.py --stream <file>   # tail-like streaming mode
    python3 jlog.py --summary <file>  # aggregate statistics

Filters:
    --level LEVEL       Filter by log level (e.g., error, warn, info)
    --after TIMESTAMP   Only logs after ISO timestamp (e.g., 2024-01-01T00:00:00)
    --before TIMESTAMP  Only logs before ISO timestamp
    --pattern PATTERN   Regex match against the full log line
    --field KEY=VALUE   Match exact field value (repeatable)
    --limit N           Max number of entries to output (default: unlimited)

Output:
    --summary           Print aggregate statistics instead of raw entries
    --no-color          Disable colorized output
    --pretty            Pretty-print JSON entries
    -o FORMAT           Output format: text (default), json, csv
"""

import argparse
import csv
import io
import json
import os
import re
import sys
import time
from collections import Counter
from datetime import datetime, timezone
from pathlib import Path
from typing import Iterator, Optional


# ── ANSI helpers ──────────────────────────────────────────────────────

class Color:
    RESET = "\033[0m"
    BOLD = "\033[1m"
    RED = "\033[31m"
    YELLOW = "\033[33m"
    GREEN = "\033[32m"
    CYAN = "\033[36m"
    GRAY = "\033[90m"

    LEVEL_MAP = {
        "fatal": RED,
        "error": RED,
        "warn": YELLOW,
        "warning": YELLOW,
        "info": GREEN,
        "debug": CYAN,
        "trace": GRAY,
    }

    @classmethod
    def level(cls, level: str) -> str:
        key = level.lower()
        color = cls.LEVEL_MAP.get(key, cls.RESET)
        return f"{color}{level}{cls.RESET}"


def supports_color() -> bool:
    return hasattr(sys.stdout, "isatty") and sys.stdout.isatty()


# ── Parsing ───────────────────────────────────────────────────────────

def parse_jsonl(path: str) -> Iterator[dict]:
    """Yield parsed JSON objects from a file (one per line)."""
    with open(path, "r", encoding="utf-8", errors="replace") as f:
        for lineno, line in enumerate(f, 1):
            line = line.strip()
            if not line:
                continue
            try:
                yield json.loads(line)
            except json.JSONDecodeError as e:
                print(f"[WARN] Line {lineno}: invalid JSON — {e}", file=sys.stderr)


def parse_ndjson_blob(path: str) -> Iterator[dict]:
    """Try loading entire file as a JSON array, falling back to JSONL."""
    with open(path, "r", encoding="utf-8", errors="replace") as f:
        raw = f.read().strip()
    if not raw:
        return
    # Try as JSON array
    if raw.startswith("["):
        try:
            for item in json.loads(raw):
                if isinstance(item, dict):
                    yield item
            return
        except json.JSONDecodeError:
            pass
    # Fall back to line-by-line
    for line in raw.splitlines():
        line = line.strip()
        if line:
            try:
                yield json.loads(line)
            except json.JSONDecodeError:
                pass


def parse_logs(path: str) -> Iterator[dict]:
    """Auto-detect format and yield log entries."""
    try:
        yield from parse_ndjson_blob(path)
    except Exception:
        yield from parse_jsonl(path)


# ── Timestamp handling ────────────────────────────────────────────────

def extract_timestamp(entry: dict) -> Optional[datetime]:
    """Try common timestamp field names."""
    for key in ("timestamp", "time", "@timestamp", "ts", "datetime", "date", "created_at"):
        val = entry.get(key)
        if val is not None:
            return parse_timestamp(val)
    return None


def parse_timestamp(val) -> Optional[datetime]:
    """Parse various timestamp formats."""
    if isinstance(val, (int, float)):
        # Unix epoch — assume seconds
        try:
            return datetime.fromtimestamp(val, tz=timezone.utc)
        except (OSError, ValueError, OverflowError):
            return None
    if isinstance(val, str):
        # ISO 8601 variants
        for fmt in (
            "%Y-%m-%dT%H:%M:%S.%f%z",
            "%Y-%m-%dT%H:%M:%S%z",
            "%Y-%m-%dT%H:%M:%S.%fZ",
            "%Y-%m-%dT%H:%M:%SZ",
            "%Y-%m-%dT%H:%M:%S",
            "%Y-%m-%d %H:%M:%S",
            "%Y-%m-%d %H:%M:%S.%f",
        ):
            try:
                dt = datetime.strptime(val, fmt)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=timezone.utc)
                return dt
            except ValueError:
                continue
        # Fallback: fromisoformat
        try:
            return datetime.fromisoformat(val)
        except (ValueError, TypeError):
            pass
    return None


def parse_cli_timestamp(val: str) -> datetime:
    """Parse a CLI-provided timestamp argument."""
    dt = parse_timestamp(val)
    if dt is None:
        raise argparse.ArgumentTypeError(f"Cannot parse timestamp: {val}")
    return dt


# ── Level extraction ──────────────────────────────────────────────────

def extract_level(entry: dict) -> Optional[str]:
    for key in ("level", "levelname", "severity", "log_level", "loglevel"):
        val = entry.get(key)
        if val is not None:
            return str(val).lower()
    return None


# ── Filtering ─────────────────────────────────────────────────────────

class LogFilter:
    def __init__(
        self,
        level: Optional[str] = None,
        after: Optional[datetime] = None,
        before: Optional[datetime] = None,
        pattern: Optional[str] = None,
        fields: Optional[dict] = None,
    ):
        self.level = level.lower() if level else None
        self.after = after
        self.before = before
        self.regex = re.compile(pattern) if pattern else None
        self.fields = fields or {}

    def matches(self, entry: dict) -> bool:
        # Level filter
        if self.level:
            entry_level = extract_level(entry)
            if entry_level != self.level:
                return False

        # Timestamp filter
        if self.after or self.before:
            ts = extract_timestamp(entry)
            if ts is None:
                return False  # can't compare — exclude
            if self.after and ts <= self.after:
                return False
            if self.before and ts >= self.before:
                return False

        # Pattern filter
        if self.regex:
            text = json.dumps(entry)
            if not self.regex.search(text):
                return False

        # Field filters
        for key, value in self.fields.items():
            # Support dot-notation for nested keys
            parts = key.split(".")
            node = entry
            for p in parts:
                if isinstance(node, dict) and p in node:
                    node = node[p]
                else:
                    return False
            if str(node).lower() != value.lower():
                return False

        return True


# ── Aggregation / Summary ─────────────────────────────────────────────

LEVEL_SEVERITY = {
    "trace": 0, "debug": 1, "info": 2, "warn": 3, "warning": 3,
    "error": 4, "fatal": 5, "critical": 5,
}


def aggregate(entries: list[dict]) -> dict:
    """Compute summary statistics from log entries."""
    total = len(entries)
    levels = Counter()
    timestamps = []
    message_lengths = []
    field_keys = Counter()
    top_fields: dict[str, Counter] = {}
    # Track first/last timestamps
    first_ts = None
    last_ts = None

    for entry in entries:
        # Level
        lvl = extract_level(entry) or "unknown"
        levels[lvl] += 1

        # Timestamps
        ts = extract_timestamp(entry)
        if ts is not None:
            timestamps.append(ts)
            if first_ts is None or ts < first_ts:
                first_ts = ts
            if last_ts is None or ts > last_ts:
                last_ts = ts

        # Message length
        for mk in ("message", "msg", "text", "body"):
            if mk in entry and isinstance(entry[mk], str):
                message_lengths.append(len(entry[mk]))
                break

        # Field key frequency
        for k in entry.keys():
            field_keys[k] += 1

    # Top values for most-common fields
    for key in field_keys.most_common(10):
        k = key[0]
        vc = Counter()
        for entry in entries:
            v = entry.get(k)
            if v is not None:
                vc[str(v)] += 1
        top_fields[k] = vc.most_common(5)

    # Time bucketing (per-hour)
    hourly = Counter()
    for ts in timestamps:
        hourly[ts.strftime("%Y-%m-%dT%H:00")] += 1

    stats = {
        "total_entries": total,
        "time_range": {
            "first": first_ts.isoformat() if first_ts else None,
            "last": last_ts.isoformat() if last_ts else None,
            "duration_hours": (
                round((last_ts - first_ts).total_seconds() / 3600, 2)
                if first_ts and last_ts else None
            ),
        },
        "level_counts": dict(levels),
        "unique_levels": len(levels),
        "hourly_distribution": dict(sorted(hourly.items())),
        "field_presence": dict(field_keys.most_common()),
        "top_field_values": {
            k: dict(v) for k, v in top_fields.items() if k not in ("message", "msg", "body")
        },
    }
    if message_lengths:
        stats["message_length"] = {
            "min": min(message_lengths),
            "max": max(message_lengths),
            "avg": round(sum(message_lengths) / len(message_lengths), 1),
        }
    return stats


# ── Output formatting ─────────────────────────────────────────────────

def format_text_entry(entry: dict, use_color: bool) -> str:
    """Format a single log entry as a human-readable line."""
    ts = extract_timestamp(entry)
    ts_str = ts.strftime("%Y-%m-%d %H:%M:%S.%f")[:23] if ts else "—"
    lvl = extract_level(entry) or "—"
    msg = entry.get("message") or entry.get("msg") or entry.get("text") or ""
    if not msg:
        # Fallback: use the entry minus known metadata
        skip = {"timestamp", "time", "@timestamp", "ts", "level", "levelname", "severity"}
        remaining = {k: v for k, v in entry.items() if k.lower() not in skip}
        if remaining:
            msg = json.dumps(remaining, ensure_ascii=False)
        else:
            msg = json.dumps(entry, ensure_ascii=False)

    if use_color:
        lvl_colored = Color.level(lvl)
        ts_colored = f"{Color.GRAY}{ts_str}{Color.RESET}"
        return f"{ts_colored} {Color.BOLD}{lvl_colored:<7}{Color.RESET} {msg}"
    return f"{ts_str}  {lvl:<7} {msg}"


def print_summary(stats: dict, use_color: bool):
    """Print a formatted summary report."""
    C = Color if use_color else type("NoColor", (), {"BOLD": "", "RESET": "", "RED": "", "YELLOW": "", "GREEN": "", "CYAN": "", "GRAY": "", "level": lambda s, c: s})()

    print(f"\n{C.BOLD}{'═' * 60}")
    print(f"  JSON LOG ANALYSIS SUMMARY")
    print(f"{'═' * 60}{C.RESET}\n")

    print(f"  Total entries:  {C.BOLD}{stats['total_entries']}{C.RESET}")
    print(f"  Unique levels:  {stats['unique_levels']}")

    tr = stats["time_range"]
    if tr["first"]:
        print(f"  Time range:     {tr['first']} → {tr['last']}")
        if tr["duration_hours"] is not None:
            print(f"  Duration:       {tr['duration_hours']}h")
    print()

    # Level breakdown
    print(f"  {C.BOLD}Level Breakdown:{C.RESET}")
    severity_order = sorted(stats["level_counts"].keys(), key=lambda x: LEVEL_SEVERITY.get(x.lower(), 99))
    for lvl in severity_order:
        count = stats["level_counts"][lvl]
        pct = count / stats["total_entries"] * 100 if stats["total_entries"] else 0
        bar_len = int(pct / 5)
        bar = "█" * bar_len + "░" * (20 - bar_len)
        lvl_str = C.level(lvl) if use_color else lvl
        print(f"    {lvl_str:<10} {count:>8}  {C.GRAY}{bar}{C.RESET} {pct:.1f}%")
    print()

    # Hourly distribution (show up to 20 buckets)
    hourly = stats["hourly_distribution"]
    if hourly:
        print(f"  {C.BOLD}Hourly Distribution (top 20):{C.RESET}")
        max_count = max(hourly.values())
        for hour, count in list(hourly.items())[-20:]:
            bar_len = int(count / max_count * 30) if max_count else 0
            bar = "▓" * bar_len
            print(f"    {C.GRAY}{hour}  {C.RESET}{bar} {count}")
        print()

    # Message length stats
    if "message_length" in stats:
        ml = stats["message_length"]
        print(f"  {C.BOLD}Message Length:{C.RESET}  min={ml['min']}  max={ml['max']}  avg={ml['avg']}")
        print()

    # Top field values
    top = stats.get("top_field_values", {})
    if top:
        print(f"  {C.BOLD}Top Field Values:{C.RESET}")
        for field, values in list(top.items())[:5]:
            val_str = ", ".join(f"{k}: {v}" for k, v in list(values.items())[:3])
            print(f"    {field}: {C.GRAY}{val_str}{C.RESET}")
        print()

    print(f"{C.BOLD}{'═' * 60}{C.RESET}\n")


def output_csv(entries: list[dict]):
    """Output entries as CSV."""
    if not entries:
        return
    # Collect all keys
    all_keys: list[str] = []
    seen: set[str] = set()
    for e in entries:
        for k in e.keys():
            if k not in seen:
                all_keys.append(k)
                seen.add(k)

    writer = csv.DictWriter(sys.stdout, fieldnames=all_keys, extrasaction="ignore")
    writer.writeheader()
    writer.writerows(entries)


def output_json(entries: list[dict], pretty: bool):
    """Output entries as JSON."""
    indent = 2 if pretty else None
    print(json.dumps(entries, indent=indent, ensure_ascii=False))


# ── Streaming mode ────────────────────────────────────────────────────

def stream_file(path: str, log_filter: LogFilter, use_color: bool, pretty: bool,
                output_fmt: str, limit: Optional[int]):
    """Tail-like streaming: follow file and print new entries."""
    # Read existing content first
    initial_entries = list(parse_logs(path))
    shown = 0
    for entry in initial_entries:
        if log_filter.matches(entry):
            _print_entry(entry, use_color, pretty, output_fmt)
            shown += 1
            if limit and shown >= limit:
                return

    # Now follow the file
    try:
        size = os.path.getsize(path)
    except OSError:
        return

    print(f"--- following {path} (Ctrl+C to stop) ---", file=sys.stderr)

    try:
        while True:
            time.sleep(0.5)
            try:
                new_size = os.path.getsize(path)
            except OSError:
                continue
            if new_size > size:
                with open(path, "r", encoding="utf-8", errors="replace") as f:
                    f.seek(size)
                    new_data = f.read()
                size = new_size
                for line in new_data.splitlines():
                    line = line.strip()
                    if not line:
                        continue
                    try:
                        entry = json.loads(line)
                        if isinstance(entry, dict) and log_filter.matches(entry):
                            _print_entry(entry, use_color, pretty, output_fmt)
                            shown += 1
                            if limit and shown >= limit:
                                return
                    except json.JSONDecodeError:
                        pass
    except KeyboardInterrupt:
        print("\n--- stopped ---", file=sys.stderr)


def _print_entry(entry: dict, use_color: bool, pretty: bool, output_fmt: str):
    if output_fmt == "json":
        indent = 2 if pretty else None
        print(json.dumps(entry, indent=indent, ensure_ascii=False))
    elif output_fmt == "csv":
        writer = csv.DictWriter(sys.stdout, fieldnames=list(entry.keys()), extrasaction="ignore")
        writer.writerow(entry)
    else:
        if pretty:
            print(json.dumps(entry, indent=2, ensure_ascii=False))
        else:
            print(format_text_entry(entry, use_color))


# ── CLI ───────────────────────────────────────────────────────────────

def main():
    parser = argparse.ArgumentParser(
        prog="jlog",
        description="JSON Log Analyzer — parse, filter, aggregate, and stream JSON logs.",
        epilog="Examples:\n"
               "  jlog.py app.jsonl --level error\n"
               "  jlog.py app.jsonl --after 2024-01-01 --before 2024-02-01\n"
               "  jlog.py app.jsonl --pattern 'timeout|connection refused'\n"
               "  jlog.py app.jsonl --summary\n"
               "  jlog.py app.jsonl --stream\n"
               "  jlog.py app.jsonl --field user_id=123 --output csv\n",
        formatter_class=argparse.RawDescriptionHelpFormatter,
    )
    parser.add_argument("files", nargs="+", help="JSON log files to analyze")

    # Filters
    filter_group = parser.add_argument_group("Filters")
    filter_group.add_argument("--level", "-l", help="Filter by log level")
    filter_group.add_argument("--after", type=parse_cli_timestamp, help="Only entries after this timestamp")
    filter_group.add_argument("--before", type=parse_cli_timestamp, help="Only entries before this timestamp")
    filter_group.add_argument("--pattern", "-p", help="Regex pattern to match against full entry")
    filter_group.add_argument("--field", "-f", action="append", default=[],
                              help="Filter by field value (KEY=VALUE, supports dot notation)")
    filter_group.add_argument("--limit", "-n", type=int, default=0, help="Max entries to output")

    # Modes
    mode_group = parser.add_argument_group("Modes")
    mode_group.add_argument("--summary", "-s", action="store_true", help="Show aggregate statistics")
    mode_group.add_argument("--stream", "-t", action="store_true", help="Tail-like streaming mode (follow file)")

    # Output
    output_group = parser.add_argument_group("Output")
    output_group.add_argument("--output", "-o", choices=["text", "json", "csv"], default="text", help="Output format")
    output_group.add_argument("--pretty", action="store_true", help="Pretty-print JSON entries")
    output_group.add_argument("--no-color", action="store_true", help="Disable colorized output")

    args = parser.parse_args()

    use_color = supports_color() and not args.no_color

    # Parse field filters
    fields = {}
    for f in args.field:
        if "=" not in f:
            parser.error(f"Invalid field filter '{f}', expected KEY=VALUE")
        k, v = f.split("=", 1)
        fields[k] = v

    log_filter = LogFilter(
        level=args.level,
        after=args.after,
        before=args.before,
        pattern=args.pattern,
        fields=fields,
    )

    limit = args.limit if args.limit > 0 else None

    # Streaming mode (single file only)
    if args.stream:
        if len(args.files) > 1:
            parser.error("Streaming mode supports only a single file")
        stream_file(args.files[0], log_filter, use_color, args.pretty, args.output, limit)
        return

    # Collect entries from all files
    all_entries: list[dict] = []
    for path in args.files:
        if not os.path.isfile(path):
            print(f"[ERROR] File not found: {path}", file=sys.stderr)
            sys.exit(1)
        for entry in parse_logs(path):
            if log_filter.matches(entry):
                all_entries.append(entry)
                if limit and len(all_entries) >= limit:
                    break
        if limit and len(all_entries) >= limit:
            break

    # Summary mode
    if args.summary:
        stats = aggregate(all_entries)
        if args.output == "json":
            print(json.dumps(stats, indent=2))
        else:
            print_summary(stats, use_color)
        return

    # Output entries
    if not all_entries:
        if use_color:
            print(f"{Color.GRAY}(no matching entries){Color.RESET}", file=sys.stderr)
        return

    if args.output == "json":
        output_json(all_entries, args.pretty)
    elif args.output == "csv":
        output_csv(all_entries)
    else:
        for entry in all_entries:
            _print_entry(entry, use_color, args.pretty, args.output)


if __name__ == "__main__":
    main()
